    "id": "revisao-siadap-processo-paritaria-composicao",
    "law": "siadap",
    "topic": "SIADAP 3: processo, garantias e controlo",
    "subtopic": "Comissão paritária",
    "familyId": "siadap:revisao-processo-paritaria-composicao",
