    "id": "revisao-siadapportaria-fichas-nucleares",
    "law": "siadapportaria",
    "topic": "SIADAP: competências, comportamentos e fichas",
    "subtopic": "Escolha de competências",
    "familyId": "siadapportaria:revisao-fichas-nucleares",
    "conceptId": "siadapportaria:revisao-fichas-nucleares",
