    "id": "revisao-siadapram-trabalhadores-discordancia",
    "law": "siadapram",
    "topic": "SIADAP-RAM 3: requisitos, parâmetros e efeitos",
    "subtopic": "Contratualização dos parâmetros",
    "familyId": "siadapram:revisao-trabalhadores-discordancia",
